import type { Clock } from "@sanity/workflow-engine";
import type { DeclaredExecutionContext } from "@sanity/workflow-engine";
import type { EffectHandler } from "@sanity/workflow-engine";
import type { Engine } from "@sanity/workflow-engine";
import type { EngineEffectsArgs } from "@sanity/workflow-engine";
import type { EngineLogger } from "@sanity/workflow-engine";
import type { WorkflowClient } from "@sanity/workflow-engine";
import type { WorkflowDeployment } from "@sanity/workflow-engine";
import type { WorkflowTelemetryLogger } from "@sanity/workflow-engine";

/** The handlers a beat registers and the `catchUp` argument that matches them.
 *  {@link beatCatchUp} keeps the two in step. */
export declare interface BeatCatchUp {
  handlers: Record<string, EffectHandler>;
  args: HeartbeatCatchUpArgs;
}

/**
 * Pick one beat's catch-up: every effect in `effectNames` without a declared
 * budget, plus one of `budgetedEffectNames`, whose turn the beat's own clock
 * decides, spreading the turns so that beats arriving every nth slot rather
 * than every slot still reach each budgeted effect. One invocation registers
 * at most one budgeted handler.
 *
 * Throws when `effectNames` is empty, when `registry` holds no handler for a
 * name in `effectNames`, when a `budgetedEffectNames` entry is not in
 * `effectNames`, when `afterMs` is not a positive finite number, or, when it is
 * selecting a budgeted effect, when `clock` returns a value that is not an
 * instant. `afterMs` is one beat in
 * milliseconds and also the period the budgeted turn rotates over, so widening
 * the recovery window slows that rotation by the same factor. `clock` defaults
 * to the wall clock. Pass the result straight through: `handlers` to the
 * engine's `effects` with `missingHandler: 'skip'`, and `args` as `catchUp`.
 */
export declare function beatCatchUp(args: {
  registry: Readonly<Record<string, EffectHandler>>;
  effectNames: readonly string[];
  budgetedEffectNames: readonly string[];
  recoverDefinitions: readonly string[];
  afterMs: number;
  clock?: Clock;
}): BeatCatchUp;

/** An engine scoped to `deployment`, and the client it runs on, for use inside a Sanity
 *  Function handler. Throws unless the deployment's workflow resource is a dataset and
 *  either `options.context` carries a token or `options.clientFactory` is supplied. */
export declare function createRuntimeEngine(
  deployment: RuntimeDeployment,
  options: CreateRuntimeEngineOptions,
): {
  engine: Engine;
  client: WorkflowClient;
};

export declare interface CreateRuntimeEngineOptions {
  /** The context the handler was invoked with. Its `clientOptions.token` and
   *  `clientOptions.apiHost` authorize the client. */
  context: RuntimeFunctionContext;
  /** Advisory provenance stamped on the engine's writes. Defaults to a
   *  `server` kind identified by the deployment's robot-token name. */
  execution?: DeclaredExecutionContext;
  effects?: EngineEffectsArgs;
  telemetry?: WorkflowTelemetryLogger;
  clock?: Clock;
  /** Overrides client construction. Defaults to {@link defaultClientFactory}. */
  clientFactory?: RuntimeClientFactory;
}

/** A CDN-less client pinned to the engine's API version, on the raw perspective. */
export declare const defaultClientFactory: RuntimeClientFactory;

/** One beat of the generated heartbeat's schedule, in milliseconds: how long a
 *  never-claimed effect must have waited before a beat looks for it. */
export declare const HEARTBEAT_BEAT_MS = 60000;

/** Which entries make a beat drain an instance: the ones no drainer is working
 *  on, whether they were never claimed or their claim's lease lapsed. */
export declare interface HeartbeatCatchUpArgs {
  /**
   * Effect names to look for. An instance holding none of them in that state is
   * not drained by this beat, whether it is in flight or completed.
   *
   * The beat drains only these names, and runs
   * {@link HeartbeatCatchUpArgs.budgetedEffect} at most once across the whole
   * invocation. Register handlers for exactly these names.
   */
  effectNames: readonly string[];
  /**
   * Version-less definition names whose instances this beat recovers,
   * independent of the `definitions` it ticks.
   */
  recoverDefinitions: readonly string[];
  /**
   * How long an entry must have been pending and never claimed to count, in
   * milliseconds, strictly. Use one beat, so an entry the write that queued it
   * already sent to a drain is not looked for. An entry whose claim's lease has
   * lapsed counts whatever its age, since no drainer is holding it either.
   *
   * This bounds which instances a beat drains, not which of their entries it
   * dispatches: a fresh unbudgeted entry goes out beside an overdue one.
   * {@link HeartbeatCatchUpArgs.budgetedEffect} is capped at one entry.
   */
  afterMs: number;
  /**
   * The one effect with a declared budget this beat may run, if any. The beat
   * drains a single instance holding it and leaves the rest to later beats. That
   * dispatch comes first: only the candidate query and that instance's claim
   * sweep run before it, and ticks and unbudgeted recovery follow it. Size the
   * hosting function for that handler's own declaration. Pass the name
   * {@link beatCatchUp} chose, whose handler is the only budgeted one it
   * registered.
   */
  budgetedEffect?: string;
}

export declare interface HeartbeatResult {
  /** Instances this pass worked on: every in-flight instance of `definitions`,
   *  plus every instance of {@link HeartbeatCatchUpArgs.recoverDefinitions}
   *  holding an entry the catch-up looked for, completed ones included. */
  total: number;
  changed: number;
  /** Stale effect claims the sweep released. */
  released: number;
  /** Pending effects the catch-up drain settled successfully. */
  caughtUp: number;
  /** Pending effects the catch-up drain settled as failed, or dispatched
   *  without settling because another party settled them first. Each one is
   *  logged at error level with its instance. */
  caughtUpUnsettled: number;
  /** Instances whose sweep, catch-up or tick threw. A failed effect does not
   *  throw, so it is counted above instead. */
  failed: number;
  /** Instances whose budgeted dispatch this beat withheld, because another
   *  instance had already taken its one run of
   *  {@link HeartbeatCatchUpArgs.budgetedEffect}. Their unbudgeted entries are
   *  drained all the same, and a later beat takes the budgeted one. */
  deferred: number;
}

/**
 * Release stale effect claims and tick every in-flight instance of
 * `definitions` in `tag`, in one pass. A failing instance is counted, not
 * thrown; instance failures make the call throw only when at least one
 * candidate ran and every one failed. It also throws before reaching any
 * instance when `tag` is not a valid engine tag, when `catchUp.afterMs` is not
 * a positive finite number, when `catchUp.effectNames` is empty, or when
 * `catchUp.budgetedEffect` is not in `catchUp.effectNames`. `execution` stamps the release rows and `log`
 * defaults to the engine's console logger.
 *
 * Pass `catchUp` to also drain instances holding an entry no drainer is working
 * on: one queued before its drain function existed or while the drain was down,
 * or one whose claim's lease lapsed. A completed instance holding such an entry
 * is drained too, and never ticked. The engine must hold a handler for each
 * named effect, and `effects.missingHandler: 'skip'` so an entry it cannot run
 * stays pending for whatever hosts it.
 *
 * `definitions` are version-less definition names, and an empty list ticks
 * nothing. Recovery has its own list, so a beat that ticks nothing still
 * recovers the queues in {@link HeartbeatCatchUpArgs.recoverDefinitions}.
 */
export declare function runHeartbeat(args: {
  engine: Engine;
  client: WorkflowClient;
  tag: string;
  definitions: readonly string[];
  execution: Required<DeclaredExecutionContext>;
  catchUp?: HeartbeatCatchUpArgs;
  clock?: Clock;
  log?: EngineLogger;
}): Promise<HeartbeatResult>;

export declare interface RuntimeClientConfig {
  projectId: string;
  dataset: string;
  token?: string;
  /** Set only for a non-default API host. */
  apiHost?: string;
}

/** Builds the client a handler's engine runs on. An implementation must use the raw
 *  perspective: the tick and the post-effect cascade evaluate subject drafts and
 *  release versions. */
export declare type RuntimeClientFactory = (
  config: RuntimeClientConfig,
) => WorkflowClient;

export declare type RuntimeDeployment = Pick<
  WorkflowDeployment,
  "tag" | "workflowResource" | "resourceAliases"
>;

/** Both the document and the scheduled function context satisfy this structurally. */
export declare interface RuntimeFunctionContext {
  clientOptions?:
    | {
        token?: string;
        apiHost?: string;
      }
    | undefined;
}

export {};
